/**
 * Builds the reviewed contract summary deterministically from APPROVED items.
 * No LLM is involved: the summary can only contain what a human approved, with citations.
 */

export const DISCLAIMER =
  'This summary is generated by an information-management tool from items a reviewer approved. ' +
  'It is not legal advice and may be incomplete; always refer to the signed contract.';

const cite = (item) =>
  (item.citations ?? [])
    .map((c) => `${c.documentRole === 'policy' ? 'Policy ' : ''}§${c.sectionRef}${c.verified ? '' : ' (unverified)'}`)
    .join(', ');

function entry(item, extra = {}) {
  return {
    itemId: item.id,
    label: item.label,
    text: item.currentValue.summary,
    responsibleParty: item.responsibleParty ?? null,
    certainty: item.certainty,
    edited: Boolean(item.isEdited),
    potentiallyStale: item.tier === 'stale',
    sources: cite(item),
    ...extra,
  };
}

function anchorLine(label, anchor) {
  return { label, date: anchor.date ?? null, detail: anchor.date ? anchor.calculation ?? null : anchor.reason ?? null };
}

/**
 * @param {{ contract, latestVersion, approvedItems: Array, reviewCounts: object, schedule: object, generatedAt: string }} input
 */
export function buildSummary({ contract, latestVersion, approvedItems, reviewCounts, schedule, generatedAt }) {
  const byType = (type) => approvedItems.filter((item) => item.itemType === type);
  const nextDateFor = new Map(schedule.deadlines.map((d) => [d.itemId, d]));

  const summary = {
    disclaimer: DISCLAIMER,
    contract: { id: contract.id, title: contract.title, versionNumber: latestVersion.versionNumber },
    generatedAt,
    asOf: schedule.asOf,
    reviewStatus: {
      ...reviewCounts,
      complete: reviewCounts.pending === 0 && reviewCounts.potentiallyStale === 0,
    },
    parties: byType('party').map((item) => entry(item)),
    keyDates: [
      anchorLine('Effective date', schedule.anchors.effectiveDate),
      anchorLine('Original expiry', schedule.anchors.expiryDate),
      ...(schedule.anchors.autoRenews ? [anchorLine('Current term ends (auto-renewal)', schedule.anchors.currentTermEnd)] : []),
    ],
    renewal: byType('renewal').map((item) => entry(item, { nextDate: nextDateFor.get(item.id)?.date ?? null })),
    termination: byType('termination').map((item) => entry(item, { nextDate: nextDateFor.get(item.id)?.date ?? null })),
    notice: byType('notice').map((item) => entry(item, { nextDate: nextDateFor.get(item.id)?.date ?? null })),
    obligations: byType('obligation').map((item) =>
      entry(item, {
        nextDate: nextDateFor.get(item.id)?.date ?? null,
        recurrence: item.currentValue.recurrence ?? null,
      }),
    ),
    issues: [...byType('ambiguity'), ...byType('conflict')].map((item) => entry(item, { type: item.itemType })),
    openQuestions: approvedItems
      .filter((item) => item.clarificationQuestion)
      .map((item) => ({ itemId: item.id, label: item.label, question: item.clarificationQuestion, sources: cite(item) })),
    upcomingDeadlines: schedule.deadlines
      .filter((d) => d.status !== 'overdue')
      .slice(0, 10)
      .map((d) => ({ date: d.date, label: d.label, kind: d.kind, responsibleParty: d.responsibleParty })),
  };

  return { ...summary, markdown: toMarkdown(summary) };
}

function listSection(title, entries, render) {
  if (entries.length === 0) return [`## ${title}`, '', '_None approved._', ''];
  return [`## ${title}`, '', ...entries.map(render), ''];
}

const flags = (e) =>
  [e.potentiallyStale ? '⚠ potentially stale' : null, e.certainty === 'interpretation' ? 'interpretation' : null, e.edited ? 'reviewer-corrected' : null]
    .filter(Boolean)
    .map((flag) => ` _(${flag})_`)
    .join('');

const line = (e) =>
  `- **${e.label}**: ${e.text}${e.responsibleParty ? ` — responsible: ${e.responsibleParty}` : ''}${e.nextDate ? ` — next date: ${e.nextDate}` : ''} [${e.sources}]${flags(e)}`;

export function toMarkdown(s) {
  const status = s.reviewStatus;
  return [
    `# Reviewed contract summary: ${s.contract.title}`,
    '',
    `> ${s.disclaimer}`,
    '',
    `Version ${s.contract.versionNumber} · generated ${s.generatedAt} · dates as of ${s.asOf}`,
    '',
    `Review status: ${status.approved} approved, ${status.pending} pending, ${status.rejected} rejected, ${status.potentiallyStale} potentially stale.` +
      (status.complete ? '' : ' **Review is incomplete; this summary covers approved items only.**'),
    '',
    ...listSection('Parties', s.parties, line),
    '## Key dates',
    '',
    ...s.keyDates.map((d) => `- **${d.label}**: ${d.date ?? 'not determined'}${d.detail ? ` — ${d.detail}` : ''}`),
    '',
    ...listSection('Renewal', s.renewal, line),
    ...listSection('Termination', s.termination, line),
    ...listSection('Notice requirements', s.notice, line),
    ...listSection('Obligations', s.obligations, (e) => `${line(e)}${e.recurrence && e.recurrence !== 'none' ? ` _(recurs ${e.recurrence})_` : ''}`),
    ...listSection('Unclear or conflicting terms', s.issues, line),
    ...listSection('Open clarification questions', s.openQuestions, (q) => `- ${q.question} — re: ${q.label} [${q.sources}]`),
    ...listSection('Upcoming deadlines', s.upcomingDeadlines, (d) => `- ${d.date} — ${d.label}${d.responsibleParty ? ` (${d.responsibleParty})` : ''}`),
  ].join('\n');
}
